import XCTest
@testable import NativeTestSeam
final class GenericReplacementTests:XCTestCase {
  func activation(_ token:GenerationToken,verified:Bool=true)throws->InterruptionActivation{let vad=ConfirmedSpeechInterruption(token);var event:InterruptionActivation?;for _ in 0..<8{event=vad.advance(1,independentUserSpeech:verified)};return try XCTUnwrap(event)}
  func testOldSpeechCancelledBeforeExactlyOneReplacement()throws{let time=FakeTime(),c=testController(clock:time,scheduler:time),s=NativeClauseQueueTests.Sink();XCTAssertTrue(c.dispatch(.start));XCTAssertTrue(c.dispatch(.speechDetected,token:c.token));let old=c.token!;var receive:((UnsafeBufferPointer<UInt8>)throws->Void)?,finish:((LlmJobResult)->Void)?
    let first=GenericSpokenTurn(controller:c,token:old,sink:s,configured:true,starter:{_,_,r,f in receive=r;finish=f;try! Array("First. Second. ".utf8).withUnsafeBufferPointer{try r($0)};return true});XCTAssertTrue(first.submit(AsrText(text:"Hello.",final:true),confidence:1));s.callbacks[0](.started)
    let event=try activation(old);var starts=0;let replacement=try XCTUnwrap(GenericSpokenTurn.replacing(event,controller:c,sink:s,configured:true,independentSpeechStillVerified:{true},starter:{_,request,r,f in starts+=1;XCTAssertTrue(request.history.isEmpty);try! Array("Blue.".utf8).withUnsafeBufferPointer{try r($0)};f(.completed);return true}));XCTAssertTrue(old.cancelled);XCTAssertGreaterThan(s.stops,0);XCTAssertTrue(c.recognitionAllowed(c.token!));XCTAssertFalse(c.recognitionAllowed(old));XCTAssertNil(event.apply(c,independentSpeechStillVerified:{true}))
    XCTAssertTrue(replacement.submit(AsrText(text:"Name one colour.",final:true),confidence:1));XCTAssertFalse(replacement.submit(AsrText(text:"Duplicate.",final:true),confidence:1));XCTAssertThrowsError(try Array("Stale.".utf8).withUnsafeBufferPointer{try receive!($0)});finish?(.completed);s.callbacks[0](.finished);XCTAssertEqual(s.texts,["First.","Blue."]);s.callbacks[1](.started);s.callbacks[1](.finished);XCTAssertEqual(c.state,.standby);XCTAssertEqual(starts,1)
  }
  func testDefaultAndLostSeparationCannotReplaceOrRecognize()throws{let c=NativeClauseQueueTests().controller(),s=NativeClauseQueueTests.Sink(),old=c.token!,q=try XCTUnwrap(NativeClauseQueue.create(controller:c,token:old,sink:s,authorized:{_,_ in true}));q.enqueue("First.");s.callbacks[0](.started);let event=try activation(old);XCTAssertNil(GenericSpokenTurn.replacing(event,controller:c,sink:s));XCTAssertNil(GenericSpokenTurn.replacing(event,controller:c,sink:s,configured:true));XCTAssertFalse(old.cancelled);var verified=true;let next=try XCTUnwrap(event.apply(c,independentSpeechStillVerified:{verified}));XCTAssertTrue(c.recognitionAllowed(next));verified=false;XCTAssertFalse(c.recognitionAllowed(next));c.stop();verified=true;XCTAssertFalse(c.recognitionAllowed(next))}
  func testAppOutputVadAndStalePrivacyNeverCreateTurn()throws{let c=NativeClauseQueueTests().controller(),old=c.token!,vad=ConfirmedSpeechInterruption(old);for _ in 0..<100{XCTAssertNil(vad.advance(1,independentUserSpeech:false))};let event=try activation(old);_ = c.privacyTransition(.lock);XCTAssertNil(event.apply(c,independentSpeechStillVerified:{true}));XCTAssertEqual(c.state,.stopped)}
}
